insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('choose-activity-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Choose Activity', 'An activity that builds understanding limits.', null, 'Ongoing', '3 activity options', 'Offer 3 activities and let child choose. ''What would you like to do first?'' Autonomous choice builds decision-making.', 'This builds the emotional vocabulary and self-control that make the preschool years easier. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('deal-disappointment-script-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Deal Disappointment Script', 'An activity that builds emotional regulation and social play.', 4, '3–5 min', 'None', 'When something doesn''t happen as planned, narrate: ''You''re disappointed. That was important to you. Let''s think about what we can do.''', 'Your toddler is starting to notice other people''s feelings, which is the beginning of empathy. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('fairness-conversations-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Fairness Conversations', 'An activity that builds emotional regulation and social play.', 7, '5–8 min', 'None', 'Is it fair that she got 3 and you got 2?'' Fairness reasoning appears at 2.5 years and is important to take seriously.', 'This builds the emotional vocabulary and self-control that make the preschool years easier. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('cornstarch-goop-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Cornstarch Goop', 'A hands-on activity for developing water play and sensory regulation.', 18, '15–20 min', 'Cornstarch and water', 'Mix cornstarch and water: it''s both solid and liquid. Scientifically bizarre sensory experience. Let child explore freely.', 'This helps your toddler''s nervous system distinguish between different sensations, which supports focus and calm. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('sound-walk-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Sound Walk', 'A playful challenge that strengthens auditory discrimination.', 18, '15–20 min', 'None (outdoors)', 'Walk outside listening only: no talking. Point at sounds. Back home, draw or describe what you heard. Auditory attention focus.', 'Rich sensory experience at this stage feeds language too, because it gives children something worth describing. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('temperature-sensory-bin-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Temperature Sensory Bin', 'A playful challenge that strengthens tactile discrimination.', 13, '10–15 min', 'Ice, warm water, container', 'Ice cubes in a bin of warm water. Feeling both together, watching ice melt. Temperature + observation + language.', 'Sensory play remains genuinely developmental at this age, supporting both regulation and fine motor skill. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('yoga-kids-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Yoga Kids', 'An activity that builds vestibular and proprioceptive input.', 8, '5–10 min', 'None', 'Teach 3 simple yoga poses: tree, mountain, downward dog. Proprioceptive + balance + breath awareness combined.', 'This helps your toddler''s nervous system distinguish between different sensations, which supports focus and calm. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('top-or-gyroscope-m28_30', 'cognitive'::domain, 'm28_30'::age_band, 'Top or Gyroscope', 'A hands-on activity for developing vestibular and proprioceptive input.', 7, '5–8 min', 'Top (or any spinning object)', 'Let child spin a top and watch. The visual tracking of a spinning object is uniquely absorbing at this age.', 'Sensory play remains genuinely developmental at this age, supporting both regulation and fine motor skill. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('pour-own-drink-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Pour Own Drink', 'A playful challenge that strengthens pouring and drinking independently.', null, 'Ongoing', 'Small jug and cup', 'Pour their own water from a small child-sized jug into a cup at meals. Independence in self-care + fine motor + self-regulation.', 'Your toddler is now capable of real independence in daily routines, and doing so builds confidence as much as skill. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AAP Toilet Training Guidance; AOTA Activities of Daily Living; IAP'),
  ('help-set-table-m28_30', 'social_emotional'::domain, 'm28_30'::age_band, 'Help Set Table', 'A playful challenge that strengthens contributing to household tasks.', 8, '5–10 min', 'Tableware', 'Carry plates, fold napkins, place cutlery. Table-setting is fine motor + sequencing + contribution to family life.', 'Your toddler is now capable of real independence in daily routines, and doing so builds confidence as much as skill. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('hop-5-times-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Hop 5+ Times', 'A hands-on activity for developing jumping and explosive leg power.', 4, '3–5 min', 'None', 'Sustained hopping on one foot: first dominant then non-dominant. Non-dominant hopping develops several months after dominant.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('broad-jump-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Broad Jump', 'An activity that builds jumping and explosive leg power.', 4, '3–5 min', 'Tape', 'Mark a starting line with tape. Jump forward as far as possible, both feet together. Measure distance: it increases weekly.', 'Your toddler is becoming genuinely capable physically, and this builds the strength and coordination that running, climbing and jumping all need. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('throw-vertical-target-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Throw Vertical Target', 'A playful challenge that strengthens throwing, catching and hand-eye coordination.', 7, '5–8 min', 'Soft ball, tape on wall', 'Tape a target circle on the wall at chest height. Throw a soft ball to hit it. Aimed at a vertical target = new motor challenge.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('tricycle-fast-slow-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Tricycle Fast Slow', 'A playful challenge that strengthens pedalling and steering.', 13, '10–15 min', 'Tricycle', 'Pedal fast when you say go, slow when you say stop. Speed regulation while pedalling requires real-time motor control.', 'Your toddler is becoming genuinely capable physically, and this builds the strength and coordination that running, climbing and jumping all need. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('backward-balance-beam-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Backward Balance Beam', 'A hands-on activity for developing static and dynamic balance.', 7, '5–8 min', 'Tape line', 'With you standing right beside them ready to steady them, walk backward along a balance beam (tape line). Balance plus motor sequencing in an unusual direction.', 'Your toddler is becoming genuinely capable physically, and this builds the strength and coordination that running, climbing and jumping all need. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('obstacle-course-run-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Obstacle Course Run', 'A hands-on activity for developing running and speed control.', 13, '10–15 min', 'Chairs, cushions, tape, ball', 'A full obstacle course: run, jump over, crawl under, balance on, throw at. Complex movement sequence requiring memory of order.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('throw-run-combination-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Throw Run Combination', 'A playful challenge that strengthens running and speed control.', 8, '5–10 min', 'Ball', 'Throw a ball, run to get it, throw again. Sequencing two motor actions with a transition tests motor working memory.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('marching-place-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Marching Place', 'A hands-on activity for developing functional strength and carrying.', 8, '5–10 min', 'Music source', 'Lift knees high and march in time to music. Rhythmic bilateral motor coordination and gross motor control.', 'Your toddler is becoming genuinely capable physically, and this builds the strength and coordination that running, climbing and jumping all need. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('copy-drawing-square-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Copy Drawing Square', 'An activity that builds pre-writing control.', 8, '5–10 min', 'Crayon and paper', 'Square (4 equal sides, 4 corners) is harder than a circle: requires direction changes at precise points. Appears ~33–36 months.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('draw-person-ii-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Draw Person II', 'An activity that builds pre-writing control.', 8, '5–10 min', 'Crayon and paper', 'Head, eyes, arms, legs. Drawing a person with 4 identifiable features is a 3-year representational drawing milestone.', 'Hand control is sharpening quickly now, and this builds toward the precision that drawing, cutting and dressing need. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('cut-curved-line-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Cut Curved Line', 'A playful challenge that strengthens pre-writing control.', 8, '5–10 min', 'Child scissors and paper', 'After mastering straight-line cutting, introduce a curve to cut along. Following a curve requires continuous adjustment.', 'This strengthens the small muscles of the hand, which matters long before a pencil is ever picked up seriously. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('button-large-buttons-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Button Large Buttons', 'A hands-on activity for developing pincer grasp and tool use.', 8, '5–10 min', 'Shirt or coat with large buttons', 'Demonstrate and let child practice buttoning a shirt or coat with large buttons. Fine pincer + hand-eye coordination.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('weave-paper-strips-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Weave Paper Strips', 'A playful challenge that strengthens hand control and dexterity.', 13, '10–15 min', 'Paper strips in two colours', 'Weave paper strips over and under to make a simple mat. The alternating pattern requires sustained visual-motor tracking.', 'Hand control is sharpening quickly now, and this builds toward the precision that drawing, cutting and dressing need. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('trace-letters-m31_33', 'motor'::domain, 'm31_33'::age_band, 'Trace Letters', 'A playful challenge that strengthens pre-writing control.', 8, '5–10 min', 'Paper with large name printed', 'Trace the letters of own name with a finger, then crayon. Letter tracing before writing = spatial learning of letter forms.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('700-900-word-vocabulary-m31_33', 'communication'::domain, 'm31_33'::age_band, '700–900 Word Vocabulary', 'A playful challenge that strengthens sentence building.', null, 'Ongoing', 'None', 'By 33 months, vocabulary typically 700–900 words with 5–6 word sentences used consistently.', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('why-conversation-chain-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Why'' Conversation Chain', 'A hands-on activity for developing asking and answering questions.', 8, '5–10 min', 'None', 'Follow a chain of ''why'' questions: ''Why does it rain?'' → ''Because the clouds get heavy.'' → ''Why do they get heavy?'' Sustain 3 turns.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('all-basic-colours-m31_33', 'communication'::domain, 'm31_33'::age_band, 'All Basic Colours', 'A playful challenge that strengthens descriptive vocabulary.', 4, '3–5 min', 'Coloured objects', 'Red, blue, green, yellow, orange, purple, black, white. Naming all basic colours correctly is a 3-year language milestone.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('use-plurals-correctly-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Use Plurals Correctly', 'A playful challenge that strengthens sentence building.', null, 'Ongoing', 'None', 'Two dogs, three cats.'' Plural ''-s'' rule solidifying. Point out examples: ''Look: two birds. Birds: more than one.''', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('tense-regular-verbs-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Tense Regular Verbs', 'An activity that builds sentence building.', null, 'Ongoing', 'None', 'I walked. We played. She jumped.'' Regular past tense (-ed) appearing. Irregular past (''went'', ''ran'') still developing.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('what-you-see-m31_33', 'communication'::domain, 'm31_33'::age_band, 'What You See', 'An activity that builds sentence building.', 8, '5–10 min', 'Any detailed picture or illustration', 'Tell me everything you see in this picture.'' Descriptive language drill: vocabulary, grammar, and observation combined.', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Praise the effort and the trying rather than the result, especially when it does not go well.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('conditional-sentences-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Conditional Sentences', 'A playful challenge that strengthens sentence building.', 8, '5–10 min', 'None', 'If we water the plant, it will grow.'' If-then reasoning expressed in language: logical thinking made verbal.', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('letter-sound-introduction-m31_33', 'communication'::domain, 'm31_33'::age_band, 'Letter Sound Introduction', 'A hands-on activity for developing sentence building and vocabulary.', 7, '5–8 min', 'Paper with 3 letters printed', 'Introduce 3 letter sounds: ''A says ah, B says bah, M says mah.'' Sound-letter pairs before letter names: phonics groundwork.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Praise the effort and the trying rather than the result, especially when it does not go well.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('count-15-meaning-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Count 15 Meaning', 'A playful challenge that strengthens early number sense.', 7, '5–8 min', '15 small objects', 'Extend counting to 15 objects with one-to-one correspondence. Counting past 10 requires learning the teen number pattern.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('all-basic-shapes-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'All Basic Shapes', 'An activity that builds spatial reasoning.', 7, '5–8 min', 'Shape cut-outs or drawings', 'Circle, square, triangle, rectangle, oval. Naming all 5 basic shapes by name = geometry milestone at 33 months.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('more-fewer-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'More Fewer', 'An activity that builds sorting and categorising.', 7, '5–8 min', 'Two groups of objects', 'Place 3 objects here and 5 there. ''Which group has more?'' Comparative quantity: not counting, but visual quantity judgement.', 'Sorting, counting and matching all begin here, and they begin through play rather than instruction. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('memory-game-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Memory Game', 'A playful challenge that strengthens sorting and categorising.', 13, '10–15 min', '12 cards in 6 matching pairs', '6 matching pairs face-down. Turn 2, find matches. Working memory and concentration targeted directly.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('sequence-story-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Sequence Story', 'A playful challenge that strengthens symbolic and pretend thinking.', 8, '5–10 min', '4 sequential pictures', '4 story pictures out of order. Can child arrange them in logical sequence? Narrative + causal reasoning combined.', 'Sorting, counting and matching all begin here, and they begin through play rather than instruction. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('first-middle-last-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'First, Middle, Last', 'A playful challenge that strengthens sequencing.', 7, '5–8 min', '3 objects in a line', 'Line up 3 objects. ''Which is first? Last? Middle?'' Ordinal position language builds mathematical foundation.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('friend-concept-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Friend Concept', 'A hands-on activity for developing cooperative play.', 8, '5–10 min', 'None', 'Who is your friend? What do you like about them?'' Friendship awareness at 31–33 months is a social milestone.', 'Regulation at this age still depends heavily on a calm adult nearby, and that is exactly as it should be. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('turns-group-game-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Turns Group Game', 'An activity that builds sharing and turn-taking.', 13, '10–15 min', 'Group game', 'Play a group game with 3–4 children where turns rotate. Supporting turn-taking in a group is more complex than in a pair.', 'Regulation at this age still depends heavily on a calm adult nearby, and that is exactly as it should be. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('accepting-no-practice-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Accepting ''No'' Practice', 'A playful challenge that strengthens understanding limits.', null, 'Ongoing', 'None', 'When a request must be declined, practice accepting it with words: ''Okay, maybe later.'' Delayed gratification is teachable.', 'Your toddler is starting to notice other people''s feelings, which is the beginning of empathy. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('cooperative-drawing-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Cooperative Drawing', 'A hands-on activity for developing cooperative play.', 8, '5–10 min', 'Large paper and crayons for two', 'Two people draw on the same paper at the same time. Sharing a creative space without conflict is social maturity.', 'This builds the emotional vocabulary and self-control that make the preschool years easier. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('identify-emotions-others-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Identify Emotions Others', 'An activity that builds emotional vocabulary and awareness.', null, 'Ongoing', 'None', 'Dadi looks tired today. What do you think she needs?'' Reading real (not illustrated) emotional states is a harder skill.', 'Your toddler is starting to notice other people''s feelings, which is the beginning of empathy. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('comfort-peer-distress-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Comfort Peer Distress', 'A playful challenge that strengthens cooperative play.', null, 'Ongoing', 'None', 'When another child is upset: ''Can you think of something that might help them feel better?'' Pro-social action seeded.', 'Regulation at this age still depends heavily on a calm adult nearby, and that is exactly as it should be. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('mud-kitchen-play-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Mud Kitchen Play', 'A playful challenge that strengthens water play and sensory regulation.', 25, '20–30 min', 'Soil, water, pots, spoons (outdoors)', 'Outdoors: soil, water, pots, spoons. Make ''food'', serve it, clean up. Sensory + imaginative + gross + fine motor all together.', 'This helps your toddler''s nervous system distinguish between different sensations, which supports focus and calm. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('shadow-play-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Shadow Play', 'An activity that builds sensory discrimination.', 13, '10–15 min', 'Sunlight or torch', 'In bright sunlight, make and change shadow shapes. Tracing shadows on paper. Visual perception + fine motor + science.', 'Rich sensory experience at this stage feeds language too, because it gives children something worth describing. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('magnet-exploration-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Magnet Exploration', 'A playful challenge that strengthens sensory discrimination.', 13, '10–15 min', 'Magnet (fridge magnet) + household objects', 'A magnet and various household objects. Which ones stick? Systematic testing of a material property.', 'Sensory play remains genuinely developmental at this age, supporting both regulation and fine motor skill. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('rhythm-clapping-patterns-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Rhythm Clapping Patterns', 'A playful challenge that strengthens auditory discrimination.', 7, '5–8 min', 'None', 'Clap a 3-beat pattern and ask child to copy. Grade to 4-beat. Rhythmic working memory and motor sequencing.', 'This helps your toddler''s nervous system distinguish between different sensations, which supports focus and calm. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('blindfold-texture-guess-m31_33', 'cognitive'::domain, 'm31_33'::age_band, 'Blindfold Texture Guess', 'An activity that builds tactile discrimination.', 8, '5–10 min', 'Blindfold + household objects', 'Blindfold or closed eyes; feel an object and name it. Tactile recognition without visual aid.', 'Rich sensory experience at this stage feeds language too, because it gives children something worth describing. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('prepare-simple-snack-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Prepare Simple Snack', 'A playful challenge that strengthens pouring and drinking independently.', 13, '10–15 min', 'Simple food preparation items', 'Peel a banana, spread butter on toast, pour cereal. Contributing to own food preparation builds self-care and agency.', 'Competence at this age builds a sense of capability that praise alone cannot. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AAP Toilet Training Guidance; AOTA Activities of Daily Living; IAP'),
  ('dress-independently-m31_33', 'social_emotional'::domain, 'm31_33'::age_band, 'Dress Independently', 'An activity that builds dressing independence.', 8, '5–10 min', 'Clothing', 'By 33 months: pull trousers up/down, put on shoes (even wrong feet), put on hat, take off jacket. Independence in sequence.', 'This reduces the daily friction of routines by giving your child a genuine role in them. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AAP Toilet Training Guidance; AOTA Activities of Daily Living; IAP'),
  ('skip-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Skip', 'A playful challenge that strengthens jumping and explosive leg power.', 8, '5–10 min', 'None', 'True skipping (step-hop alternating feet) typically appears 3.5–4 years. Practice the step-hop on each foot separately first.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('throw-catch-iii-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Throw Catch III', 'A playful challenge that strengthens throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Tennis ball or similar', 'Tennis-ball-sized throw and catch at 2 metres. Smaller ball demands greater precision than large-ball catching.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('hop-10-times-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Hop 10+ Times', 'A hands-on activity for developing jumping and explosive leg power.', 4, '3–5 min', 'None', '10+ consecutive hops on the preferred foot. Non-preferred foot at this stage is typically 5–8 hops.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('jump-over-line-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Jump Over Line', 'A playful challenge that strengthens jumping and explosive leg power.', 4, '3–5 min', 'Two tape lines', 'Mark two lines 40 cm apart. Jump from one to the other with both feet. Distance increases as leg strength and timing improve.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('balance-one-foot-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Balance One Foot', 'A playful challenge that strengthens static and dynamic balance.', 4, '3–5 min', 'None', '5-second one-foot balance without support. Practice eyes open then eventually eyes closed.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('dribble-ball-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Dribble Ball', 'A hands-on activity for developing throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Medium ball', 'Bounce and catch a ball repeatedly. Dribbling (bouncing without catching) is harder and typically 4–5 years.', 'Movement at this age is how the body''s control systems get calibrated, and children who move more move better. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('move-music-i-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Move Music I', 'An activity that builds rhythm and coordinated movement.', 8, '5–10 min', 'Music source', 'Move to the beat of different musical styles. Rhythmic entrainment (body movement matching musical tempo) is a motor milestone.', 'This is a good age for challenging the balance system, because the body is stable enough to try and still learning fast. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('gallop-object-hand-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Gallop Object Hand', 'An activity that builds whole-body strength and coordination.', 8, '5–10 min', 'Small lightweight object', 'Gallop while holding an object in one hand. Dual-task motor automatisation: galloping becomes automatic enough for a second task.', 'Your toddler is becoming genuinely capable physically, and this builds the strength and coordination that running, climbing and jumping all need. Praise the effort and the trying rather than the result, especially when it does not go well.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('copy-drawing-triangle-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Copy Drawing Triangle', 'A hands-on activity for developing pre-writing control.', 8, '5–10 min', 'Crayon and paper', 'Triangle requires three directional line changes at precise angles. Typically appearing 36 months: harder than square.', 'This strengthens the small muscles of the hand, which matters long before a pencil is ever picked up seriously. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('draw-person-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Draw Person', 'A playful challenge that strengthens pre-writing control.', 8, '5–10 min', 'Crayon and paper', 'Head, body, 2 arms, 2 legs. By 36 months: 6-part person is the benchmark drawing milestone.', 'Hand control is sharpening quickly now, and this builds toward the precision that drawing, cutting and dressing need. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('copy-first-name-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Copy First Name', 'A playful challenge that strengthens pre-writing control.', 8, '5–10 min', 'Paper with large name printed', 'Trace each letter of first name carefully. Letter-form learning happens through the motor movement, not just visual recognition.', 'Hand control is sharpening quickly now, and this builds toward the precision that drawing, cutting and dressing need. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('child-scissors-shape-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Child Scissors Shape', 'A hands-on activity for developing pre-writing control.', 8, '5–10 min', 'Child scissors and paper', 'Cut out a simple shape (circle or triangle) drawn on paper. Following curved and angular lines in cutting.', 'This strengthens the small muscles of the hand, which matters long before a pencil is ever picked up seriously. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('paper-into-envelope-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Paper into Envelope', 'A playful challenge that strengthens spatial placement.', 8, '5–10 min', 'Paper', 'Fold a piece of paper in thirds and tuck in the edges to make a simple envelope. Spatial folding and precise crease-making.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('complex-block-structures-m34_36', 'motor'::domain, 'm34_36'::age_band, 'Complex Block Structures', 'A hands-on activity for developing bilateral coordination and spatial precision.', 13, '10–15 min', 'Blocks', 'Build a house, bridge, or tower using a picture as a model. Copying a 3D structure from a 2D picture is abstract spatial cognition.', 'Your toddler''s hands can now do far more than a year ago, and this stretches that capability a little further. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('1000-word-vocabulary-m34_36', 'communication'::domain, 'm34_36'::age_band, '1000+ Word Vocabulary', 'A hands-on activity for developing vocabulary growth.', null, 'Ongoing', 'None', 'At 36 months, vocabulary typically 900–1200 words. Strangers should understand 75–100% of speech by this age.', 'Sentences are forming now, and children build them by hearing slightly more complex language than they can produce. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('retell-story-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Retell Story', 'A hands-on activity for developing asking and answering questions.', 8, '5–10 min', 'Familiar book', 'After reading a book, ask child to retell it in order without pictures. 4-event sequence recall is the 3-year target.', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('past-future-tense-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Past Future Tense', 'An activity that builds sentence building.', null, 'Ongoing', 'None', 'Yesterday I played. Tomorrow we will go.'' Past and future tense correct usage is a 3-year grammar milestone.', 'Sentences are forming now, and children build them by hearing slightly more complex language than they can produce. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('something-works-i-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Something Works I', 'A playful challenge that strengthens asking and answering questions.', 8, '5–10 min', 'None', 'Why does the ball roll? Why does the fan spin?'' 3-year-olds begin to explain mechanisms, not just name them.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('letter-sound-game-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Letter Sound Game', 'A playful challenge that strengthens asking and answering questions.', 7, '5–8 min', 'None', 'What sound does S make? Dog starts with what letter?'' 5-letter sound associations by 36 months = strong phonics foundation.', 'This is a period of rapid vocabulary growth, and conversation is what fuels it. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('5-word-sentences-m34_36', 'communication'::domain, 'm34_36'::age_band, '5-Word Sentences', 'A hands-on activity for developing sentence building.', null, 'Ongoing', 'None', 'The big red dog ran away.'' Complex sentences with adjectives and adverbs consistently = strong language development.', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Praise the effort and the trying rather than the result, especially when it does not go well.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('is-x-better-m34_36', 'communication'::domain, 'm34_36'::age_band, 'is X Better?', 'A playful challenge that strengthens asking and answering questions.', 8, '5–10 min', 'None', 'Is a cat or a dog better to have? Why?'' Opinion + justification: the beginning of argument and persuasive language.', 'Language at this age develops through back-and-forth exchanges, where your toddler gets a real turn. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('rhyme-word-family-m34_36', 'communication'::domain, 'm34_36'::age_band, 'Rhyme Word Family', 'An activity that builds vocabulary growth.', 7, '5–8 min', 'None', 'Cat, bat, sat, hat, rat: all rhyme. What else rhymes with cat?'' Generating rhymes from a family = phonological fluency.', 'Sentences are forming now, and children build them by hearing slightly more complex language than they can produce. Praise the effort and the trying rather than the result, especially when it does not go well.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('count-20-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Count 20', 'A hands-on activity for developing early number sense.', 7, '5–8 min', '20 small objects', 'Count 20 objects one-to-one. Past 12, children must remember the teen pattern; past 20, the decade pattern begins.', 'Sorting, counting and matching all begin here, and they begin through play rather than instruction. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('concept-zero-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Concept Zero', 'A playful challenge that strengthens early number sense.', 7, '5–8 min', 'None', 'How many elephants are on this table? Zero. Zero means none.'' Zero as a quantity is an abstract concept to teach explicitly.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('name-10-colours-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Name 10 Colours', 'An activity that builds comparing attributes.', 7, '5–8 min', 'Coloured objects', 'Red, blue, green, yellow, orange, purple, pink, black, white, brown. Naming all 10 basic colours by 36 months is solid.', 'Sorting, counting and matching all begin here, and they begin through play rather than instruction. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('days-week-introduction-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Days Week Introduction', 'An activity that builds sequencing.', 7, '5–8 min', 'None', 'Sing or say days of the week in sequence. Memorising the sequence before understanding the concept: sequence comes first.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('pattern-prediction-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Pattern Prediction', 'A playful challenge that strengthens cause-and-effect reasoning.', 7, '5–8 min', 'Coloured objects', 'AABB pattern: red, red, blue, blue, red, red… ''What comes next?'' Two-repeat pattern is harder than ABAB.', 'This is the age where children start to reason about why things happen, not just notice that they do. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('cause-effect-explanation-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Cause-Effect Explanation', 'A hands-on activity for developing cause-and-effect reasoning.', 8, '5–10 min', 'None', 'Why did that happen? What caused it?'' Causal explanation (not just observation but mechanism) is a 3-year cognitive goal.', 'Your toddler can now hold an idea in mind and work toward it, which makes this kind of thinking activity genuinely useful. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Harvard Center on the Developing Child (Executive Function); NAEYC Play-Based Learning; IAP'),
  ('cooperative-game-i-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Cooperative Game I', 'An activity that builds cooperative play.', 13, '10–15 min', 'Simple card or board game', 'Play a simple game with explicit rules (ludo, snap). Following rules in a game is the first social contract: a major SE milestone.', 'This builds the emotional vocabulary and self-control that make the preschool years easier. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('conflict-resolution-script-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Conflict Resolution Script', 'A playful challenge that strengthens emotional regulation and social play.', 4, '3–5 min', 'None', 'Teach: ''Stop. Think. Speak.'' When a conflict happens, model the steps: pause, consider the other person, use words.', 'Your toddler is starting to notice other people''s feelings, which is the beginning of empathy. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('own-feelings-early-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Own Feelings Early', 'A playful challenge that strengthens emotional regulation.', null, 'Ongoing', 'None', 'I notice your face looks cross. Are you feeling frustrated before it comes out big?'' Self-awareness before dysregulation.', 'This builds the emotional vocabulary and self-control that make the preschool years easier. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('apology-empathy-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Apology Empathy', 'An activity that builds emotional vocabulary and awareness.', null, 'Ongoing', 'None', 'I''m sorry I took your toy. I know that made you sad.'' Empathy embedded in apology: what they did + how the other felt.', 'Your toddler is starting to notice other people''s feelings, which is the beginning of empathy. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('winning-losing-gracefully-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Winning Losing Gracefully', 'A playful challenge that strengthens early empathy.', 13, '10–15 min', 'Game', 'Practice in a real game. Celebrate both: ''You lost this time and stayed kind. That is very hard and very mature.''', 'Your toddler is starting to notice other people''s feelings, which is the beginning of empathy. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('best-friend-identification-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Best-Friend Identification', 'An activity that builds cooperative play.', 8, '5–10 min', 'None', 'Who is your favourite person to play with? What do you do together?'' Intentional friendship at 3 is a social milestone.', 'This builds the emotional vocabulary and self-control that make the preschool years easier. Praise the effort and the trying rather than the result, especially when it does not go well.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('resist-and-wait-practice-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Resist-and-Wait Practice', 'An activity that builds sharing and turn-taking.', 4, '2–5 min', 'Timer', 'I know you want it now. Let''s wait 2 minutes together.'' Practise with a timer. Delayed gratification is a teachable executive function.', 'Regulation at this age still depends heavily on a calm adult nearby, and that is exactly as it should be. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'Zero to Three; CASEL Social-Emotional Framework; IAP'),
  ('slime-making-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Slime Making', 'A hands-on activity for developing sensory discrimination.', 18, '15–20 min', 'PVA glue, bicarbonate of soda, contact lens solution', 'Mix glue and bicarbonate of soda (or contact lens solution). Unique tactile input: stretchy, gooey, satisfying. Full sensory engagement.', 'This helps your toddler''s nervous system distinguish between different sensations, which supports focus and calm. Praise the effort and the trying rather than the result, especially when it does not go well.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('sensory-story-walk-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Sensory Story Walk', 'A hands-on activity for developing tactile discrimination.', 25, '20–30 min', 'None (outdoors)', 'Walk a route where child closes eyes at each stop and describes what they hear and feel. One sense at a time, deliberately.', 'This helps your toddler''s nervous system distinguish between different sensations, which supports focus and calm. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('nature-printing-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Nature Printing', 'A hands-on activity for developing tactile discrimination.', 13, '10–15 min', 'Leaves, paint, paper', 'Press leaves, bark, or flowers with paint onto paper. The texture transfer is visual, tactile, and creative simultaneously.', 'Sensory play remains genuinely developmental at this age, supporting both regulation and fine motor skill. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('blindfold-object-guess-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Blindfold Object Guess', 'An activity that builds tactile discrimination.', 8, '5–10 min', 'Bag + household objects', 'Feel objects in a bag without looking. Name or describe them. Pure tactile recognition with language challenge added.', 'This helps your toddler''s nervous system distinguish between different sensations, which supports focus and calm. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('rhythm-band-m34_36', 'cognitive'::domain, 'm34_36'::age_band, 'Rhythm Band', 'An activity that builds auditory discrimination.', 13, '10–15 min', 'Pots, spoons, containers', 'Assign different percussion sounds to different family members. Create a rhythm piece together. Auditory + motor + social.', 'Rich sensory experience at this stage feeds language too, because it gives children something worth describing. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('simple-self-care-sequence-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Simple Self-Care Sequence', 'A hands-on activity for developing dressing independence.', 18, '15–20 min', 'Clothing, towel, toothbrush', 'Wake, toilet, wash face, brush teeth, dress: child does as much as possible. Independence in sequence, not perfection in execution.', 'This reduces the daily friction of routines by giving your child a genuine role in them. Let them repeat it as often as they want, and let them change the rules; both are signs it is doing its job.', 'AAP Toilet Training Guidance; AOTA Activities of Daily Living; IAP'),
  ('help-household-chores-m34_36', 'social_emotional'::domain, 'm34_36'::age_band, 'Help Household Chores', 'An activity that builds contributing to household tasks.', 8, '5–10 min', 'Household items', 'Set the table, put laundry in the basket, water a plant. Contributing to household function builds competence and belonging.', 'Competence at this age builds a sense of capability that praise alone cannot. Give your toddler time to work it out before stepping in, because the working out is where the learning happens.', 'AAP Toilet Training Guidance; AOTA Activities of Daily Living; IAP'),
  ('skip-distance-challenge-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Skip Distance Challenge', 'A play-based activity for strengthening jumping, hopping and skipping.', 8, '5–10 min', 'None', 'Skip from one end of the room to the other. Alternate leading foot each trip. Distance and coordination both increase weekly.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('gallop-relay-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Gallop Relay', 'A hands-on challenge that builds coordination and physical confidence.', 8, '5–10 min', 'Small object + open space', 'Gallop to a point, pick up an object, gallop back. Combining a motor skill with a task = motor automatisation.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('throw-overhand-distance-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Throw Overhand Distance', 'A play-based activity for strengthening running and agility.', 8, '5–10 min', 'Ball', 'Increase throwing distance to 3 metres. Overhand distance throw = full shoulder rotation and trunk twist working together.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('hop-non-dominant-foot-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Hop Non-Dominant Foot', 'A hands-on challenge that builds jumping, hopping and skipping.', 4, '3–5 min', 'None', 'After mastering dominant foot hopping, work on non-dominant. Often takes 3–6 months more than dominant foot.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('pump-swing-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Pump Swing', 'An activity that develops rhythm and coordinated movement.', 13, '10–15 min', 'Swing', 'Teach the leg-pump rhythm for swinging independently. Pendulum mechanics + body coordination + rhythm = rich learning.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('jump-rope-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Jump Rope', 'An activity that develops jumping, hopping and skipping.', 8, '5–10 min', 'Rope', 'Hold rope and jump over it laid flat, then swing it slowly. Full jump rope is 5–6 years; foundations built from 3 years.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('catch-one-hand-y3_0', 'motor'::domain, 'y3_0'::age_band, 'Catch One Hand', 'A play-based activity for strengthening throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Large soft ball', 'Catch a large soft ball with one hand. Single-hand catching requires much faster visual-motor processing than two-hand.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP')
